
export const __atoms = []
export function atom(initial) {
  const a = { __initial: initial, _v: initial, get: () => a._v, set: (v) => { a._v = typeof v === 'function' ? v(a._v) : v },
              subscribe: () => () => {} }
  __atoms.push(a)
  return a
}
export function useValue(a) { return a && typeof a.get === 'function' ? a.get() : a }
